head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[image > E > onabort]<br/>Image 컴포넌트의 이미지 로딩을 강제로 중단(Esc) 시 발생합니다.",
    "validation" : [
        "Image 컴포넌트의 이미지 로딩을 강제로 중단(Esc) 시 발생합니다.",
        "IE 브라우저만 지원하며 이미지 전송을 ESC 키나 브라우저의 X 버튼으로 중단했을때 발생합니다.",
        "이벤트 객체 e (Event) 가 핸들러에 전달되어야 합니다.",
        "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다.",
        "하위 버전 호환을 위한 이벤트입니다.",
        "최신 브라우저는 img 태그에 대한 onabort 이벤트를 지원하지 않으므로 사용하지 않는 것을 권장합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정 (로딩이 끝나지 않는 주소)
    con_src.setValue("https://10.255.255.1/slow_image.png");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (scwin.target1) {
        scwin.target1.remove();
        scwin.target1 = null;
    }

    // 조건 값 조회
    let cSrc = con_src.getValue();

    // 테스트 참고 라벨
    let strLabel = "";
    strLabel += "[전제] src = " + cSrc + "\n";
    strLabel += "[절차] 응답이 지연되는 주소(수십 초간 로딩 상태 유지)를 고르고 Target 재생성 버튼을 클릭해 이미지를 다시 요청한 뒤, 로딩이 진행되는 동안 ESC 키를 누르거나 브라우저의 중단(X) 버튼을 클릭해 전송을 중단합니다.\n";
    strLabel += "[확인] 리턴 값 확인 영역에 onabort 이벤트 발생 로그가 출력되는지 확인합니다.\n";
    strLabel += "[확인] Chromium 실측에서는 로딩 중 ESC 키, 브라우저 중단(X), src 값 변경 및 제거 어느 조작으로도 abort 이벤트가 발생하지 않아 로그가 출력되지 않습니다. 중단 시 img 요소에는 abort 대신 error 이벤트가 발생하며, img 요소에 abort 이벤트를 강제로 발생시키면 핸들러가 호출되어 로그가 출력되는 것까지 확인했습니다.";

    await $c.gcm.createLabel('label="' + strLabel + '"', '', 'label1');

    // 조건 설정
    let eList = $c.gcm.createEList(["onabort"]);

    // src 를 con 값으로 가변해야 하므로 공통 함수($c.gcm.createBasicImage 는 src 고정) 대신 직접 생성한다
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:image ' + $c.gcm.strNameSpace + ' ' + eList + ' src="' + cSrc + '"></xf:image>';

    scwin.target1 = await $p.dynamicCreate("target1", "image", strTarget, grp_comp);
}



// validation 1, 2, 3, 4, 5, 6 판정 출력
scwin.target1_onabort = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onabort 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
